INSERT INTO `crop_disease_records` VALUES (15,87.12,'C:/uploads/Screenshot 2026-02-01 173933.png','Leaf Rust','2026-02-02 07:41:14.000000','Monitor drainage and reduce watering. Apply fungicide X.',1,'Caused by fungal spores that thrive in high humidity and poor air circulation.','[{\"name\":\"Mancozeb 75% WP\",\"dosage\":\"2g per liter of water\",\"frequency\":\"Every 10-15 days\",\"note\":\"Wear protective gloves and mask. Do not spray during flowering.\"},{\"name\":\"Propiconazole 25% EC\",\"dosage\":\"1ml per liter of water\",\"frequency\":\"Every 14 days\",\"note\":\"Systemic fungicide. Follow PHI (Pre-Harvest Interval) of 7 days.\"},{\"name\":\"Bordeaux Mixture\",\"dosage\":\"5g per liter of water\",\"frequency\":\"Every 10 days\",\"note\":\"Traditional copper-based fungicide. Avoid during hot weather.\"}]','[{\"name\":\"Neem Oil Spray\",\"dosage\":\"2-3 ml per liter of water\",\"frequency\":\"2-3 times weekly\",\"note\":\"Eco-friendly. Apply in early morning or evening to avoid leaf burn.\"},{\"name\":\"Garlic-Based Organic Fungicide\",\"dosage\":\"50g crushed garlic per liter\",\"frequency\":\"Once every 5 days\",\"note\":\"Natural antifungal properties. Strain before spraying.\"},{\"name\":\"Copper Soap Fungicide (Organic)\",\"dosage\":\"As per manufacturer instructions\",\"frequency\":\"Every 7-10 days\",\"note\":\"OMRI certified. Safe for organic farming.\"}]','[\"Plant resistant varieties suitable for your climate\",\"Ensure proper spacing (30-45cm) between plants for air circulation\",\"Avoid overhead watering; use drip irrigation instead\",\"Water early in the day to allow foliage to dry\",\"Remove plant debris regularly and compost away from crops\",\"Practice 2-3 year crop rotation\",\"Apply balanced fertilization to strengthen plant immunity\"]'),(16,93.5,'C:/uploads/Screenshot 2026-02-01 173933.png','Leaf Rust','2026-02-02 07:45:20.000000','Monitor drainage and reduce watering. Apply fungicide X.',1,'Caused by fungal spores that thrive in high humidity and poor air circulation.','[{\"name\":\"Mancozeb 75% WP\",\"dosage\":\"2g per liter of water\",\"frequency\":\"Every 10-15 days\",\"note\":\"Wear protective gloves and mask. Do not spray during flowering.\"},{\"name\":\"Propiconazole 25% EC\",\"dosage\":\"1ml per liter of water\",\"frequency\":\"Every 14 days\",\"note\":\"Systemic fungicide. Follow PHI (Pre-Harvest Interval) of 7 days.\"},{\"name\":\"Bordeaux Mixture\",\"dosage\":\"5g per liter of water\",\"frequency\":\"Every 10 days\",\"note\":\"Traditional copper-based fungicide. Avoid during hot weather.\"}]','[{\"name\":\"Neem Oil Spray\",\"dosage\":\"2-3 ml per liter of water\",\"frequency\":\"2-3 times weekly\",\"note\":\"Eco-friendly. Apply in early morning or evening to avoid leaf burn.\"},{\"name\":\"Garlic-Based Organic Fungicide\",\"dosage\":\"50g crushed garlic per liter\",\"frequency\":\"Once every 5 days\",\"note\":\"Natural antifungal properties. Strain before spraying.\"},{\"name\":\"Copper Soap Fungicide (Organic)\",\"dosage\":\"As per manufacturer instructions\",\"frequency\":\"Every 7-10 days\",\"note\":\"OMRI certified. Safe for organic farming.\"}]','[\"Plant resistant varieties suitable for your climate\",\"Ensure proper spacing (30-45cm) between plants for air circulation\",\"Avoid overhead watering; use drip irrigation instead\",\"Water early in the day to allow foliage to dry\",\"Remove plant debris regularly and compost away from crops\",\"Practice 2-3 year crop rotation\",\"Apply balanced fertilization to strengthen plant immunity\"]'),(17,87.08,'C:/uploads/Screenshot 2026-02-01 173933.png','Healthy','2026-02-05 04:04:27.000000','No action needed. Keep maintaining current care.',1,'Optimal soil nutrients and climate conditions maintained.','[{\"name\":\"Balanced NPK Fertilizer (19:19:19)\",\"dosage\":\"5g per liter of water\",\"frequency\":\"Every 15 days during growth\",\"note\":\"Adjust based on soil test results.\"},{\"name\":\"Micronutrient Mix (Zn, Fe, Mn, B)\",\"dosage\":\"As per soil test recommendations\",\"frequency\":\"Once every 2 months\",\"note\":\"Apply only if deficiency is confirmed through testing.\"}]','[{\"name\":\"Compost Application\",\"dosage\":\"2-3 kg per square meter\",\"frequency\":\"Every 3-4 months\",\"note\":\"Maintains soil health and beneficial microbes.\"},{\"name\":\"Organic Mulch\",\"dosage\":\"5-7 cm layer around plants\",\"frequency\":\"Replenish as needed\",\"note\":\"Conserves moisture and suppresses weeds naturally.\"},{\"name\":\"Seaweed Extract\",\"dosage\":\"2ml per liter of water\",\"frequency\":\"Monthly foliar spray\",\"note\":\"Boosts plant immunity and stress tolerance.\"}]','[\"Continue regular monitoring for early disease detection\",\"Maintain proper watering schedule based on crop needs\",\"Keep balanced nutrition through soil testing every 6 months\",\"Practice integrated pest management (IPM)\",\"Maintain soil pH between 6.0-7.0 for most crops\",\"Ensure good drainage to prevent waterlogging\",\"Rotate crops annually to prevent soil depletion\",\"Keep farm records for better decision making\"]'),(18,86.08,'C:/uploads/Screenshot 2026-02-01 173933.png','Powdery Mildew','2026-02-06 06:44:36.000000','Prune infected leaves immediately. Increase air circulation.',1,'Result of excess moisture on leaves combined with warm, stagnant air.','[{\"name\":\"Myclobutanil 10% WP\",\"dosage\":\"0.5g per liter of water\",\"frequency\":\"Every 10-14 days\",\"note\":\"Systemic action. Wear protective equipment during application.\"},{\"name\":\"Trifloxystrobin 25% + Tebuconazole 50% WG\",\"dosage\":\"0.4g per liter of water\",\"frequency\":\"Every 14 days\",\"note\":\"Broad-spectrum fungicide. PHI: 3 days.\"},{\"name\":\"Potassium Bicarbonate\",\"dosage\":\"5g per liter of water\",\"frequency\":\"Weekly\",\"note\":\"Less toxic alternative. Can be used close to harvest.\"}]','[{\"name\":\"Baking Soda Solution\",\"dosage\":\"1 tablespoon per gallon (4 liters) + few drops dish soap\",\"frequency\":\"Every 3-5 days\",\"note\":\"Safe and effective. Soap helps solution stick to leaves.\"},{\"name\":\"Milk Spray\",\"dosage\":\"40% milk, 60% water mixture\",\"frequency\":\"Twice weekly\",\"note\":\"Natural antifungal. Use fresh milk for best results.\"},{\"name\":\"Sulfur-Based Organic Fungicide\",\"dosage\":\"As per product label\",\"frequency\":\"Every 7 days\",\"note\":\"Do not apply when temperature exceeds 32°C (90°F).\"}]','[\"Choose resistant varieties for your region\",\"Provide adequate spacing (40-50cm) for air flow\",\"Avoid excessive nitrogen fertilization which promotes soft growth\",\"Water at soil level, never on leaves\",\"Prune to improve light penetration and air movement\",\"Remove infected leaves immediately and destroy\",\"Maintain soil pH between 6.0-7.0 for optimal plant health\"]'),(19,86.98,'C:/images/sample.jpg','Healthy','2026-02-06 06:47:07.000000','No action needed. Keep maintaining current care.',1,'Optimal soil nutrients and climate conditions maintained.','[{\"name\":\"Balanced NPK Fertilizer (19:19:19)\",\"dosage\":\"5g per liter of water\",\"frequency\":\"Every 15 days during growth\",\"note\":\"Adjust based on soil test results.\"},{\"name\":\"Micronutrient Mix (Zn, Fe, Mn, B)\",\"dosage\":\"As per soil test recommendations\",\"frequency\":\"Once every 2 months\",\"note\":\"Apply only if deficiency is confirmed through testing.\"}]','[{\"name\":\"Compost Application\",\"dosage\":\"2-3 kg per square meter\",\"frequency\":\"Every 3-4 months\",\"note\":\"Maintains soil health and beneficial microbes.\"},{\"name\":\"Organic Mulch\",\"dosage\":\"5-7 cm layer around plants\",\"frequency\":\"Replenish as needed\",\"note\":\"Conserves moisture and suppresses weeds naturally.\"},{\"name\":\"Seaweed Extract\",\"dosage\":\"2ml per liter of water\",\"frequency\":\"Monthly foliar spray\",\"note\":\"Boosts plant immunity and stress tolerance.\"}]','[\"Continue regular monitoring for early disease detection\",\"Maintain proper watering schedule based on crop needs\",\"Keep balanced nutrition through soil testing every 6 months\",\"Practice integrated pest management (IPM)\",\"Maintain soil pH between 6.0-7.0 for most crops\",\"Ensure good drainage to prevent waterlogging\",\"Rotate crops annually to prevent soil depletion\",\"Keep farm records for better decision making\"]'),(20,99.37,'C:/uploads/Screenshot 2026-02-01 173933.png','Leaf Rust','2026-02-12 08:17:41.000000','Monitor drainage and reduce watering. Apply fungicide X.',1,'Caused by fungal spores that thrive in high humidity and poor air circulation.','[{\"name\":\"Mancozeb 75% WP\",\"dosage\":\"2g per liter of water\",\"frequency\":\"Every 10-15 days\",\"note\":\"Wear protective gloves and mask. Do not spray during flowering.\"},{\"name\":\"Propiconazole 25% EC\",\"dosage\":\"1ml per liter of water\",\"frequency\":\"Every 14 days\",\"note\":\"Systemic fungicide. Follow PHI (Pre-Harvest Interval) of 7 days.\"},{\"name\":\"Bordeaux Mixture\",\"dosage\":\"5g per liter of water\",\"frequency\":\"Every 10 days\",\"note\":\"Traditional copper-based fungicide. Avoid during hot weather.\"}]','[{\"name\":\"Neem Oil Spray\",\"dosage\":\"2-3 ml per liter of water\",\"frequency\":\"2-3 times weekly\",\"note\":\"Eco-friendly. Apply in early morning or evening to avoid leaf burn.\"},{\"name\":\"Garlic-Based Organic Fungicide\",\"dosage\":\"50g crushed garlic per liter\",\"frequency\":\"Once every 5 days\",\"note\":\"Natural antifungal properties. Strain before spraying.\"},{\"name\":\"Copper Soap Fungicide (Organic)\",\"dosage\":\"As per manufacturer instructions\",\"frequency\":\"Every 7-10 days\",\"note\":\"OMRI certified. Safe for organic farming.\"}]','[\"Plant resistant varieties suitable for your climate\",\"Ensure proper spacing (30-45cm) between plants for air circulation\",\"Avoid overhead watering; use drip irrigation instead\",\"Water early in the day to allow foliage to dry\",\"Remove plant debris regularly and compost away from crops\",\"Practice 2-3 year crop ro